import fs from 'node:fs';
import path from 'node:path';
import { config as loadDotenv } from 'dotenv';
import { z } from 'zod';

/**
 * Single source of truth for runtime configuration.
 *
 * 1. `TEST_ENV` selects the target. Brain Town supports **local only**: the suite runs against the
 *    compose stack started by `scripts/stack.sh` (project `brain-town-e2e`). Demo and production are never targets.
 * 2. `env/.env.<TEST_ENV>` (git-ignored, generated by `npm run env:init`) is loaded if it exists.
 *    Variables already present in `process.env` (shell exports) always win.
 * 3. Everything is validated with zod so a missing/invalid value fails fast with a readable message.
 *
 * The same env file also feeds `docker compose` (admin credentials, ArcadeDB password, ingest limits),
 * so the suite and the stack always agree. Never read `process.env` directly in tests or page objects.
 */

export const SUPPORTED_ENVS = ['local'] as const;
export type TestEnv = (typeof SUPPORTED_ENVS)[number];

const requestedEnv = process.env.TEST_ENV ?? 'local';
if (!(SUPPORTED_ENVS as readonly string[]).includes(requestedEnv)) {
  throw new Error(
    `TEST_ENV="${requestedEnv}" is not supported. Use one of: ${SUPPORTED_ENVS.join(', ')}.\n` +
      'Brain Town demo and production are intentionally NOT targets of this suite.',
  );
}
const testEnv = requestedEnv as TestEnv;

const envFile = path.resolve(__dirname, '..', 'env', `.env.${testEnv}`);
if (fs.existsSync(envFile)) {
  loadDotenv({ path: envFile, quiet: true });
}

const flag = z.stringbool().default(false);
const optionalUrl = z.preprocess((v) => (v === '' ? undefined : v), z.url().optional());

const schema = z.object({
  // ── Brain Town (web + api behind one nginx origin) ───────────────────────
  /** Origin of the local stack: town at /, back-office at /backoffice/, API at /api, /ingest, /events. */
  BRAIN_TOWN_URL: z.url().default('http://127.0.0.1:18280'),
  // ── Streaming endpoints (SSE) ─────────────────────────────────────────────
  /** Public SSE stream. Optional; defaults to `${BRAIN_TOWN_URL}/events`. */
  SSE_EVENTS_URL: optionalUrl,
  // ── Feed puller fixture (an https JSON Feed served inside the compose network) ─
  /** Base URL of the feed fixture as the api container sees it. */
  FEED_FIXTURE_URL: z.url().default('https://feed-fixture:8443'),
  // ── Ingest limits the stack was started with (the rate-limit spec reads them) ─
  INGEST_RATE: z.coerce.number().positive().default(50),
  INGEST_BURST: z.coerce.number().int().positive().default(200),
  // ── Admin account (generated per machine by `npm run env:init`) ───────────
  ADMIN_EMAIL: z.email(),
  ADMIN_PASSWORD: z.string().min(1),
  // ── Behaviour toggles ─────────────────────────────────────────────────────
  /** Allow tests tagged @destructive. Local only, so on by default is safe; keep the switch for symmetry. */
  ALLOW_DESTRUCTIVE: flag,
  /** Comma-separated browser projects: chromium, firefox, webkit, mobile-chrome, mobile-safari. */
  BROWSERS: z.string().default('chromium'),
  /** Optional branded browser channel, e.g. "chrome" or "msedge". */
  BROWSER_CHANNEL: z.string().optional(),
  API_TIMEOUT_MS: z.coerce.number().int().positive().default(15_000),
  /** Comma-separated hostnames that must never be targeted (Brain Town demo and production). */
  PROTECTED_HOSTS: z.string().default('town.mfardiansyah.id,town.demo.mfardiansyah.id'),
});

const parsed = schema.safeParse(process.env);
if (!parsed.success) {
  throw new Error(
    `Invalid configuration for TEST_ENV=${testEnv}:\n${z.prettifyError(parsed.error)}\n\n` +
      `Expected values in ${path.relative(process.cwd(), envFile)} or in the process environment.\n` +
      'Run `npm run env:init` to create the local env file from the committed *.example template.',
  );
}

const data = parsed.data;
export const env = {
  ...data,
  SSE_EVENTS_URL: data.SSE_EVENTS_URL ?? `${data.BRAIN_TOWN_URL.replace(/\/+$/, '')}/events`,
  TEST_ENV: testEnv,
};
export const isLocal = testEnv === 'local';
export const isCI = !!process.env.CI;

assertNoProtectedHosts();

/**
 * Fail fast if any configured URL points at a protected host (defence-in-depth against hitting demo/production).
 *
 * Every declared setting that ends in `_URL` OR whose value is an http(s) URL is checked, so a new schema key cannot
 * bypass the guard through its name. `PROTECTED_HOSTS` must never be empty.
 */
function assertNoProtectedHosts(): void {
  const protectedHosts = env.PROTECTED_HOSTS.split(',')
    .map((h) => h.trim().toLowerCase())
    .filter(Boolean);
  if (protectedHosts.length === 0) {
    throw new Error('PROTECTED_HOSTS is empty. List the Brain Town demo and production hostnames (comma-separated).');
  }
  const urls = Object.entries(env).filter(
    ([key, value]) => typeof value === 'string' && (key.endsWith('_URL') || /^https?:\/\//i.test(value)),
  );
  for (const [key, value] of urls) {
    const host = new URL(String(value)).hostname.toLowerCase();
    const labels = host.split('.');
    const underProtected = protectedHosts.some((p) => host === p || host.endsWith(`.${p}`));
    if (underProtected || labels.includes('prod') || labels.includes('production')) {
      throw new Error(`${key}=${String(value)} looks like a production/protected host. Refusing to run.`);
    }
  }
}
